script.text:

function active$&Identity;Form$(f) {
	f.add_onResponseComplete(on$&Identity;Form$ResponseComplete);
	f.setReadOnlyFields('ma_hd');
}
function init$&Identity;Form$(f) {
	var g = f.grid;
	f.setItemValues('ma_hd, ps_no, stt_rec', [g._item, g._value, g._idNumber]);
}
function close$&Identity;Form$(f) {try {f.remove_onResponseComplete(on$&Identity;Form$ResponseComplete);} catch (ex) {}}
function on$&Identity;Form$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			set$&Identity;Form$FlowScript(f);
			break;
		default:
			break;
	}
}
function set$&Identity;Form$FlowScript(f) {f._flowScript = 'insert$&Identity;Form$Retrieve$Data(this)';}


function insert$&Identity;Form$Retrieve$Data(f) {
	var g = f.getItem('dpb')._controlBehavior, z = f.grid, w = z.get_element().parentForm;
	if (g._rowCount > 0) {
		var first = true, row = 0, f1 = 'tien_pb, ma_dot', f2 = 'tien_nt, s1', fields = '';
		var k = g._getColumnOrder('tien_pb'), l0 = z._getColumnOrder('ma_hd');
		var v = $func.trim(w.getItemValue('loai_ct'));
		for (var r = 1; r <= g._rowCount; r++) {
			if (g._getItemValue(r, k) > 0) {
				if (first) row = z._activeRow;
				else {
					z._appendRow(true);
					row = z._rowCount;
				}

				var o = z._getItem(row, l0);
				o.row = row;
				insert$Retrieve$Items(g, r, z, row, fields, f1, f2);

				if (v != '2' || w.getItemValue('ma_nt') == w._baseCurrency) z.validExpression(o, [z.$a.tien], [z.$a.t_tien_nt, z.$a.t_tien], null);
					else z.validExpression(o, [z.$a.tien_tggs], [z.$a.t_tien_nt, z.$a.t_tien], null);
				if (first) first = false;
			}
		}

		if (!first) on$GridVoucherDetail$RowChange(z, w);
		z._focusWhenTabChanged();
	}
}
